import sys

class Node:
    def __init__(self, value):
        self.value = value
        self.prev = None
        self.next = None

def main():
    input_lines = sys.stdin.read().splitlines()
    n = int(input_lines[0])
    head = None
    tail = None

    for line in input_lines[1:n+1]:
        parts = line.split()
        if parts[0] == 'insert':
            x = int(parts[1])
            new_node = Node(x)
            if head is None:
                head = new_node
                tail = new_node
            else:
                new_node.next = head
                head.prev = new_node
                head = new_node
        elif parts[0] == 'delete':
            x = int(parts[1])
            current = head
            while current is not None:
                if current.value == x:
                    if current.prev:
                        current.prev.next = current.next
                    else:
                        head = current.next
                    if current.next:
                        current.next.prev = current.prev
                    else:
                        tail = current.prev
                    break
                current = current.next
        elif parts[0] == 'deleteFirst':
            if head is not None:
                if head == tail:
                    head = None
                    tail = None
                else:
                    new_head = head.next
                    new_head.prev = None
                    head = new_head
        elif parts[0] == 'deleteLast':
            if tail is not None:
                if head == tail:
                    head = None
                    tail = None
                else:
                    new_tail = tail.prev
                    new_tail.next = None
                    tail = new_tail

    res = []
    current = head
    while current is not None:
        res.append(str(current.value))
        current = current.next
    print(' '.join(res))

if __name__ == "__main__":
